<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,Audit};
final class Evaluation {
 public static function create(\PDO $p,int $u,int $programme,array $d):int {ExtendedMigrations::require($p);return Core::tx($p,function()use($p,$u,$programme,$d){$r=Policy::programme($p,$programme,true);Policy::require($p,$u,'evaluations.manage',$r);$kind=$d['kind']??'';if(!in_array($kind,['COURSE','SPEAKER','PRE_TEST','POST_TEST','QUIZ'],true))throw new \RuntimeException('Jenis evaluation tidak sah.');$questions=$d['questions']??[];if(!$questions||count($questions)>100)throw new \RuntimeException('1–100 soalan diperlukan.');foreach($questions as &$q){$q['label']=Core::text($q['label']??'',500);if(!in_array($q['type']??'',['TEXT','RATING','CHOICE'],true))throw new \RuntimeException('Jenis soalan tidak sah.');if($q['type']==='RATING'){if(!isset($q['min'],$q['max']))throw new \RuntimeException('Rating bounds eksplisit diperlukan.');$q['min']=Core::id($q['min']);$q['max']=Core::id($q['max']);if($q['min']>$q['max']||$q['max']>100)throw new \RuntimeException('Rating bounds tidak sah.');}if($q['type']==='CHOICE'){if(empty($q['options'])||count($q['options'])>20)throw new \RuntimeException('Pilihan diperlukan.');$q['options']=array_map(fn($x)=>Core::text($x,300),$q['options']);if(isset($q['answer'])&&!array_key_exists($q['answer'],$q['options']))throw new \RuntimeException('Answer key tidak sah.');}if(in_array($kind,['PRE_TEST','POST_TEST','QUIZ'],true)&&($q['type']!=='CHOICE'||!isset($q['answer'])))throw new \RuntimeException('Quiz memerlukan answer key.');}unset($q);$opens=Workflow::date($d['opens_at']??'');$closes=Workflow::date($d['closes_at']??'');if($opens>=$closes)throw new \RuntimeException('Window tidak sah.');$pass=in_array($kind,['PRE_TEST','POST_TEST','QUIZ'],true)?Workflow::number($d['pass_percent']??null,100):null;$required=$d['required_for_certificate']??null;if(!in_array($required,[0,1,'0','1'],true))throw new \RuntimeException('Polisi certificate diperlukan.');$v=(int)Database::query($p,'SELECT COALESCE(MAX(version),0)+1 FROM training_evaluations WHERE programme_id=?',[$programme])->fetchColumn();Database::query($p,'INSERT INTO training_evaluations(programme_id,version,title,kind,questions_json,required_for_certificate,pass_percent,opens_at,closes_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)',[$programme,$v,Core::text($d['title']??''),$kind,Workflow::json($questions),(int)$required,$pass,$opens,$closes,$u]);$id=(int)$p->lastInsertId();Audit::record($p,'evaluation.created',$u,(int)$r['owner_organisation_id'],(string)$id,'training');return $id;});}
 public static function publish(\PDO $p,int $u,int $id):void {Core::tx($p,function()use($p,$u,$id){$e=Database::query($p,'SELECT * FROM training_evaluations WHERE id=? FOR UPDATE',[$id])->fetch();if(!$e)throw new \RuntimeException('Evaluation tidak wujud.');$r=Policy::programme($p,(int)$e['programme_id'],true);Policy::require($p,$u,'evaluations.manage',$r);if($e['required_for_certificate']&&Database::query($p,"SELECT 1 FROM training_outputs WHERE programme_id=? AND kind='CERTIFICATE' AND status='LOCKED'",[$r['id']])->fetchColumn())throw new \RuntimeException('Certificate policy locked; void/reissue dahulu.');Database::query($p,'UPDATE training_evaluations SET published=1 WHERE id=?',[$id]);Audit::record($p,'evaluation.published',$u,(int)$r['owner_organisation_id'],(string)$id,'training');});}
 public static function form(\PDO $p,int $u,int $id,int $registration):array {$e=Database::query($p,'SELECT * FROM training_evaluations WHERE id=? AND published=1',[$id])->fetch();if(!$e)throw new \RuntimeException('Evaluation belum diterbitkan.');Workflow::registration($p,$u,(int)$e['programme_id'],$registration);$q=json_decode($e['questions_json'],true);foreach($q as &$item)unset($item['answer']);unset($item);unset($e['questions_json']);return [...$e,'questions'=>$q];}
 public static function submit(\PDO $p,int $u,int $id,int $registration,array $answers):void {Core::tx($p,function()use($p,$u,$id,$registration,$answers){$e=Database::query($p,'SELECT * FROM training_evaluations WHERE id=? AND published=1 FOR UPDATE',[$id])->fetch();if(!$e)throw new \RuntimeException('Evaluation tidak tersedia.');$reg=Workflow::registration($p,$u,(int)$e['programme_id'],$registration);$actor=Policy::actor($p,$u);if((int)$actor['staff_identity_id']!==(int)$reg['staff_identity_id'])throw new \RuntimeException('Submit oleh peserta sendiri.');$now=gmdate('Y-m-d H:i:s');if($now<$e['opens_at']||$now>$e['closes_at'])throw new \RuntimeException('Evaluation di luar window.');$q=json_decode($e['questions_json'],true);if(count($answers)!==count($q))throw new \RuntimeException('Jawab semua soalan.');$correct=0;$count=0;$out=[];foreach($q as $i=>$question){$a=$answers[$i]??null;if($question['type']==='TEXT')$a=Core::text($a,3000);elseif($question['type']==='RATING'){$a=Core::id($a);if($a<$question['min']||$a>$question['max'])throw new \RuntimeException('Rating di luar bounds.');}else{if(!is_scalar($a)||!array_key_exists((string)$a,$question['options']))throw new \RuntimeException('Pilihan tidak sah.');$a=(int)$a;if(isset($question['answer'])){$count++;if($a===(int)$question['answer'])$correct++;}}$out[]=$a;}$score=$count?round($correct*100/$count,2):null;Database::query($p,'INSERT INTO training_evaluation_answers(evaluation_id,registration_id,answers_json,score) VALUES(?,?,?,?)',[$id,$registration,Workflow::json($out),$score]);$r=Policy::programme($p,(int)$e['programme_id']);Audit::record($p,'evaluation.submitted',$u,(int)$r['owner_organisation_id'],(string)$id,'training',null,null,['registration'=>$registration,'score'=>$score]);});}
 public static function eligible(\PDO $p,int $programme,int $registration):bool {foreach(Database::query($p,'SELECT e.id,e.pass_percent,a.score,a.id AS answer_id FROM training_evaluations e LEFT JOIN training_evaluation_answers a ON a.evaluation_id=e.id AND a.registration_id=? WHERE e.programme_id=? AND e.published=1 AND e.required_for_certificate=1',[$registration,$programme])->fetchAll() as $e)if(!$e['answer_id']||$e['pass_percent']!==null&&($e['score']===null||$e['score']<$e['pass_percent']))return false;return true;}
}
